//! RPN (Reverse Polish Notation) calculator.

/// Errors from calculator operations.
#[derive(Debug, PartialEq)]
pub enum CalcError {
    StackUnderflow,
    DivisionByZero,
}

/// RPN calculator with an internal stack.
pub struct Calculator {
    stack: Vec<f64>,
}

impl Calculator {
    pub fn new() -> Self {
        Calculator { stack: Vec::new() }
    }

    /// Push a number onto the stack.
    pub fn push(&mut self, value: f64) {
        unimplemented!()
    }

    /// Pop the top value.
    pub fn pop(&mut self) -> Result<f64, CalcError> {
        unimplemented!()
    }

    /// Peek at the top value without removing it.
    pub fn peek(&self) -> Result<f64, CalcError> {
        self.stack.last().copied().ok_or(CalcError::StackUnderflow)
    }

    /// Add top two values (a + b where b is top).
    pub fn add(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Subtract top two values (a - b where b is top).
    pub fn sub(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Multiply top two values.
    pub fn mul(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Divide (a / b where b is top). Returns DivisionByZero if b == 0.
    pub fn div(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Duplicate the top value.
    pub fn dup(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Swap top two values.
    pub fn swap(&mut self) -> Result<(), CalcError> {
        unimplemented!()
    }

    /// Return current stack depth.
    pub fn depth(&self) -> usize {
        self.stack.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_push_pop() {
        let mut c = Calculator::new();
        c.push(1.0);
        c.push(2.0);
        assert_eq!(c.pop(), Ok(2.0));
        assert_eq!(c.pop(), Ok(1.0));
        assert_eq!(c.pop(), Err(CalcError::StackUnderflow));
    }

    #[test]
    fn test_add_sub() {
        let mut c = Calculator::new();
        c.push(3.0);
        c.push(4.0);
        c.add().unwrap(); // 3+4 = 7
        assert_eq!(c.peek(), Ok(7.0));
        c.push(2.0);
        c.sub().unwrap(); // 7-2 = 5
        assert_eq!(c.peek(), Ok(5.0));
    }

    #[test]
    fn test_mul_div() {
        let mut c = Calculator::new();
        c.push(6.0);
        c.push(3.0);
        c.mul().unwrap(); // 6*3 = 18
        assert_eq!(c.peek(), Ok(18.0));
        c.push(2.0);
        c.div().unwrap(); // 18/2 = 9
        assert_eq!(c.peek(), Ok(9.0));
    }

    #[test]
    fn test_div_by_zero() {
        let mut c = Calculator::new();
        c.push(5.0);
        c.push(0.0);
        assert_eq!(c.div(), Err(CalcError::DivisionByZero));
    }

    #[test]
    fn test_dup_swap() {
        let mut c = Calculator::new();
        c.push(1.0);
        c.push(2.0);
        c.dup().unwrap(); // stack: [1, 2, 2]
        assert_eq!(c.depth(), 3);
        c.pop().unwrap(); // remove dup
        c.swap().unwrap(); // stack: [2, 1]
        assert_eq!(c.pop(), Ok(1.0));
        assert_eq!(c.pop(), Ok(2.0));
    }

    #[test]
    fn test_underflow_on_operations() {
        let mut c = Calculator::new();
        assert_eq!(c.add(), Err(CalcError::StackUnderflow));
        c.push(1.0);
        assert_eq!(c.sub(), Err(CalcError::StackUnderflow));
    }
}
